package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/migrations"
)

func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}

func run() error {
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		return errors.New("DATABASE_URL environment variable is required")
	}

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	sweepInterval := time.Minute
	if raw := os.Getenv("SWEEP_INTERVAL"); raw != "" {
		parsed, err := time.ParseDuration(raw)
		if err != nil {
			return fmt.Errorf("parsing SWEEP_INTERVAL: %w", err)
		}
		sweepInterval = parsed
	}

	if err := runMigrations(databaseURL); err != nil {
		return fmt.Errorf("running migrations: %w", err)
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return fmt.Errorf("creating pgxpool: %w", err)
	}
	defer pool.Close()

	repo := campaign.NewRepository(pool)
	svc := campaign.NewService(repo)
	h := campaign.NewHandler(svc)

	sweeper := campaign.NewSweeper(repo)
	go sweeper.Run(ctx, sweepInterval)

	mux := http.NewServeMux()
	mux.HandleFunc("POST /campaigns", h.Create)
	mux.HandleFunc("GET /campaigns", h.List)
	mux.HandleFunc("GET /campaigns/{id}", h.Get)
	mux.HandleFunc("PATCH /campaigns/{id}", h.Update)
	mux.HandleFunc("DELETE /campaigns/{id}", h.Delete)
	mux.HandleFunc("POST /campaigns/{id}/pause", h.Pause)
	mux.HandleFunc("POST /campaigns/{id}/resume", h.Resume)
	mux.HandleFunc("POST /campaigns/{id}/end", h.End)
	mux.HandleFunc("POST /impression/{id}", h.Impression)
	mux.HandleFunc("GET /stats/{id}", h.Stats)

	server := &http.Server{
		Addr:    ":" + port,
		Handler: mux,
	}

	errCh := make(chan error, 1)
	go func() {
		log.Printf("listening on :%s", port)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	select {
	case err := <-errCh:
		return fmt.Errorf("server error: %w", err)
	case <-ctx.Done():
		log.Println("shutdown signal received")
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("server shutdown: %w", err)
	}

	return nil
}

func runMigrations(databaseURL string) error {
	db, err := sql.Open("pgx", databaseURL)
	if err != nil {
		return fmt.Errorf("opening db for migrations: %w", err)
	}
	defer db.Close()

	goose.SetBaseFS(migrations.FS)

	if err := goose.SetDialect("postgres"); err != nil {
		return fmt.Errorf("setting goose dialect: %w", err)
	}

	if err := goose.Up(db, "."); err != nil {
		return fmt.Errorf("goose up: %w", err)
	}

	return nil
}

package campaign

import (
	"encoding/json"
	"time"
)

const (
	StatusActive    = "active"
	StatusPaused    = "paused"
	StatusCompleted = "completed"
)

type Campaign struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Budget    int64     `json:"budget"`
	Spent     int64     `json:"spent"`
	Status    string    `json:"status"`
	StartDate time.Time `json:"start_date"`
	EndDate   time.Time `json:"end_date"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// MarshalJSON adds a computed "remaining" field. Remaining budget is never
// stored (budget - spent), so it's derived here rather than on the struct.
func (c Campaign) MarshalJSON() ([]byte, error) {
	type Alias Campaign // defined type, not an alias — drops MarshalJSON so this doesn't recurse

	// pgx returns scanned timestamps in the driver/host's local Location; the
	// instant is correct but json's RFC3339 output would print that offset
	// instead of "Z". Normalize to UTC here so every response is UTC.
	c.StartDate = c.StartDate.UTC()
	c.EndDate = c.EndDate.UTC()
	c.CreatedAt = c.CreatedAt.UTC()
	c.UpdatedAt = c.UpdatedAt.UTC()

	return json.Marshal(struct {
		Alias
		Remaining int64 `json:"remaining"`
	}{
		Alias:     Alias(c),
		Remaining: c.Budget - c.Spent,
	})
}

type CreateInput struct {
	Title     string      `json:"title"`
	Budget    json.Number `json:"budget"`
	StartDate time.Time   `json:"start_date"`
	EndDate   time.Time   `json:"end_date"`
}

// UpdateInput uses pointers so "field absent" (nil) is distinguishable from
// "field sent" — required for PATCH's partial-update semantics.
type UpdateInput struct {
	Title     *string      `json:"title"`
	Budget    *json.Number `json:"budget"`
	StartDate *time.Time   `json:"start_date"`
	EndDate   *time.Time   `json:"end_date"`
}

// Stats is the smaller /stats/{id} shape (no title/dates/timestamps).
type Stats struct {
	Impressions int64  `json:"impressions"`
	Spent       int64  `json:"spent"`
	Remaining   int64  `json:"remaining"`
	Budget      int64  `json:"budget"`
	Status      string `json:"status"`
}

// Stats derives impressions from spent — impressions aren't stored as a
// separate counter, since 1 impression always equals 1 unit spent.
func (c Campaign) Stats() Stats {
	return Stats{
		Impressions: c.Spent,
		Spent:       c.Spent,
		Remaining:   c.Budget - c.Spent,
		Budget:      c.Budget,
		Status:      c.Status,
	}
}

