package campaign

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type Repository struct {
	pool *pgxpool.Pool
}

func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

const campaignColumns = "id, title, budget, spent, status, start_date, end_date, created_at, updated_at"

func (r *Repository) Create(ctx context.Context, c Campaign) (Campaign, error) {
	query := `
		INSERT INTO campaigns (title, budget, start_date, end_date)
		VALUES ($1, $2, $3, $4)
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, c.Title, c.Budget, c.StartDate, c.EndDate).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

func (r *Repository) List(ctx context.Context) ([]Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE deleted_at IS NULL
		ORDER BY created_at DESC`

	rows, err := r.pool.Query(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	campaigns := []Campaign{} // non-nil so a zero-row result marshals to [] not null
	for rows.Next() {
		var c Campaign
		if err := rows.Scan(
			&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
			&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
		); err != nil {
			return nil, err
		}
		campaigns = append(campaigns, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return campaigns, nil
}

func (r *Repository) GetByID(ctx context.Context, id int64) (Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE id = $1 AND deleted_at IS NULL`

	var c Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
		&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

// Update applies a partial update, using COALESCE so an absent (nil) field
// keeps the column's current value. Both invariants below are enforced as
// WHERE conditions rather than checked beforehand in Go, so they're evaluated
// by Postgres atomically against the current row under lock as part of this
// single statement — race-safe across multiple backend instances without any
// extra locking on our side:
//   - spent <= COALESCE(budget, budget): a no-op when budget isn't being
//     changed (spent <= budget already holds via the CHECK constraint), and
//     the real budget-decrease-vs-spent guard when it is.
//   - dates only touchable while paused: vacuously true when neither date
//     param is set, otherwise requires status = 'paused'.
//
// Zero matching rows surfaces as pgx.ErrNoRows via Scan, same as GetByID.
func (r *Repository) Update(ctx context.Context, id int64, title *string, budget *int64, startDate, endDate *time.Time) (Campaign, error) {
	// Params are explicitly cast (::text/::bigint/::timestamptz) because when
	// every optional field but one is nil, Postgres can't always infer a
	// placeholder's type from COALESCE/IS NULL context alone and rejects the
	// query with "could not determine data type of parameter" (42P08).
	query := `
		UPDATE campaigns
		SET
			title      = COALESCE($2::text, title),
			budget     = COALESCE($3::bigint, budget),
			start_date = COALESCE($4::timestamptz, start_date),
			end_date   = COALESCE($5::timestamptz, end_date),
			updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status <> 'completed'
			AND spent <= COALESCE($3::bigint, budget)
			AND (($4::timestamptz IS NULL AND $5::timestamptz IS NULL) OR status = 'paused')
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id, title, budget, startDate, endDate).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// SoftDelete never issues a DELETE statement — it sets deleted_at, and every
// query elsewhere filters deleted_at IS NULL. No status restriction: any
// non-deleted campaign, regardless of status, can be soft-deleted.
func (r *Repository) SoftDelete(ctx context.Context, id int64) error {
	query := `
		UPDATE campaigns
		SET deleted_at = now(), updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL
		RETURNING id`

	var returnedID int64
	return r.pool.QueryRow(ctx, query, id).Scan(&returnedID)
}

// Pause is the same conditional-UPDATE idiom as Update/Deduct: the WHERE
// clause is the sole enforcement mechanism, so zero matching rows surfaces
// as pgx.ErrNoRows and gets disambiguated by classifyUpdateConflict.
func (r *Repository) Pause(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'paused', updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL AND status = 'active'
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// Resume: spent < budget and end_date > now() are evaluated by Postgres
// atomically against the current row as part of this one statement, so a
// concurrent impression exhausting the budget at the same instant can't
// race past this check — whichever statement runs first wins, and the other
// correctly sees the post-write state.
func (r *Repository) Resume(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'active', updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status = 'paused'
			AND spent < budget
			AND end_date > now()
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// End works from either 'active' or 'paused' — only 'completed' blocks it.
func (r *Repository) End(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'completed', updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL AND status <> 'completed'
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// CompletePastEndDate marks every active/paused campaign whose end_date has
// passed as completed. This is a catch-up sweep, not a correctness
// mechanism — Deduct and Resume already check dates themselves — so a
// missed or delayed sweep can't let an impression through past end_date.
func (r *Repository) CompletePastEndDate(ctx context.Context) (int64, error) {
	query := `
		UPDATE campaigns
		SET status = 'completed', updated_at = now()
		WHERE deleted_at IS NULL
			AND status IN ('active', 'paused')
			AND end_date <= now()`

	tag, err := r.pool.Exec(ctx, query)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}

// Deduct atomically records one impression: increments spent by 1 and, if
// this deduction exhausts the budget, flips status to 'paused' in the same
// statement — no separate transition step, so no window where a concurrent
// call could sneak in between "deduct" and "pause". The WHERE clause is the
// sole correctness mechanism, evaluated by Postgres against the current row
// under lock as part of this one statement, so it's race-safe across
// multiple backend instances without any extra locking on our side.
func (r *Repository) Deduct(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET
			spent  = spent + 1,
			status = CASE WHEN spent + 1 >= budget THEN 'paused' ELSE status END,
			updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status = 'active'
			AND start_date <= now()
			AND end_date > now()
			AND spent < budget
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

